import sys
from collections import Counter

def main():
    data = sys.stdin.read().split()
    r, c, d = int(data[0]), int(data[1]), int(data[2])
    g = data[3:3 + r]
    w = data[3 + r]
    cnt = Counter(''.join(g))
    for ch, k in Counter(w).items():
        if cnt[ch] < k:
            print('false')
            return
    if cnt[w[0]] > cnt[w[-1]]:
        w = w[::-1]
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    if d == 8:
        dirs += [(1, 1), (1, -1), (-1, 1), (-1, -1)]
    L = len(w)
    seen = [[False] * c for _ in range(r)]

    def dfs(i, j, k):
        if k == L - 1:
            return True
        seen[i][j] = True
        ch = w[k + 1]
        for di, dj in dirs:
            a, b = i + di, j + dj
            if 0 <= a < r and 0 <= b < c and not seen[a][b] and g[a][b] == ch:
                if dfs(a, b, k + 1):
                    seen[i][j] = False
                    return True
        seen[i][j] = False
        return False

    for i in range(r):
        for j in range(c):
            if g[i][j] == w[0] and dfs(i, j, 0):
                print('true')
                return
    print('false')

main()

